package com.fireplatform.simexpiry;

import com.fireplatform.simexpiry.SimExpiryModels.Page;
import com.fireplatform.shared.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import static com.fireplatform.simexpiry.SimExpiryModels.*;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class SimExpiryQueries {
    private final JdbcTemplate jdbc;private final PageSizePolicy sizes;private final TransactionRequirements transactions;private final DeviceAccessScope deviceScope;
    private static final java.time.format.DateTimeFormatter UTC_MICROS=new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter(java.util.Locale.ROOT);
    public SimExpiryQueries(JdbcTemplate jdbc,PageSizePolicy sizes,TransactionRequirements transactions,DeviceAccessScope deviceScope){this.jdbc=jdbc;this.sizes=sizes;this.transactions=transactions;this.deviceScope=deviceScope;}
    private static String timestamp(OffsetDateTime value){if(value==null)return null;if(value.getNano()%1000!=0)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","提醒时间精度无法确认");return UTC_MICROS.format(value.toInstant());}
    private static boolean fixedTimestamp(String value){if(value==null||value.length()!=27||value.startsWith("0000-"))return false;try{return UTC_MICROS.format(java.time.Instant.from(UTC_MICROS.parse(value))).equals(value);}catch(java.time.DateTimeException e){return false;}}
    private Pagination pagination(int page,Integer requested){long defaultSize=sizes.defaultPageSize();Limits.SettingDefinition policy=Limits.SETTINGS.get("default_page_size");if(defaultSize<policy.min()||defaultSize>policy.max())throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","分页配置无法确认");try{return Pagination.of(page,requested,defaultSize);}catch(IllegalArgumentException e){throw ApiError.bad("分页参数无效");}}
    public Config config(String tenant){
        var rows=jdbc.query("SELECT tenant_id,enabled,timezone,lead_days,repeat_interval_days,repeat_count,revision,updated_at FROM sim_expiry_config WHERE tenant_id=?",(r,n)->new Config(r.getString(1),r.getBoolean(2),r.getString(3),(Integer)r.getObject(4),(Integer)r.getObject(5),(Integer)r.getObject(6),r.getLong(7),timestamp(r.getObject(8,OffsetDateTime.class))),tenant);
        if(rows.isEmpty())return new Config(tenant,false,null,null,null,null,0,null);
        Config c=rows.getFirst();
        boolean complete=c.timezone()!=null&&c.lead_days()!=null&&c.repeat_interval_days()!=null&&c.repeat_count()!=null&&c.lead_days()>=0&&c.repeat_interval_days()>=1&&c.repeat_count()>=0;
        boolean empty=c.timezone()==null&&c.lead_days()==null&&c.repeat_interval_days()==null&&c.repeat_count()==null&&!c.enabled();
        if(c.revision()<1||c.revision()>9_007_199_254_740_991L||(!complete&&!empty)||c.enabled()&&!complete||!fixedTimestamp(c.updated_at())||c.timezone()!=null&&!java.time.ZoneId.getAvailableZoneIds().contains(c.timezone()))throw new ApiError(503,"SIM_EXPIRY_CONFIG_UNCONFIRMED","到期提醒配置无法确认");
        return c;
    }
    public Config readConfig(String tenant){transactions.repeatableReadOnly();return config(tenant);}
    public Page<Recipient> readRecipients(String tenant,int page,Integer requested){transactions.repeatableReadOnly();return recipients(tenant,page,requested);}
    public Page<Round> readRounds(String tenant,String user,String state,int page,Integer requested,boolean recipientOnly){transactions.repeatableReadOnly();return rounds(tenant,user,state,page,requested,recipientOnly);}
    public boolean eligible(String user,String tenant){return jdbc.queryForObject("SELECT COUNT(*) FROM app_users u JOIN user_tenant_grants g ON g.user_id=u.id AND g.tenant_id=? JOIN effective_user_permissions p ON p.user_id=u.id AND p.permission='sim-expiry:read' WHERE u.id=? AND u.user_type='PLATFORM' AND u.enabled=TRUE AND u.must_change_password=FALSE",Long.class,tenant,user)==1;}
    private Recipient recipientRow(ResultSet r,String tenant)throws SQLException{String user=r.getString("user_id"),added=timestamp(r.getObject("added_at",OffsetDateTime.class));if(user==null||user.isEmpty()||user.length()>64||user.chars().anyMatch(Character::isISOControl)||!fixedTimestamp(added))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","收件人无法确认");return new Recipient(user,added,eligible(user,tenant));}
    public Recipient recipient(String tenant,String user){var rows=jdbc.query("SELECT user_id,added_at FROM sim_expiry_recipients WHERE tenant_id=? AND user_id=?",(r,n)->recipientRow(r,tenant),tenant,user);if(rows.isEmpty())return null;if(rows.size()!=1)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","收件人无法确认");return rows.getFirst();}
    public Page<Recipient> recipients(String tenant,int page,Integer requested){Pagination p=pagination(page,requested);long total=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_recipients WHERE tenant_id=?",Long.class,tenant);var items=jdbc.query("SELECT user_id,added_at FROM sim_expiry_recipients WHERE tenant_id=? ORDER BY added_at,user_id LIMIT ? OFFSET ?",(r,n)->recipientRow(r,tenant),tenant,p.size(),p.offset());return new Page<>(items,total,p.page(),p.size(),(int)(total/p.size()+(total%p.size()==0?0:1)));}
    private static final String ROUND="SELECT id,tenant_id,target_kind,target_id,expires_on,generation,state,revision,reminder_count,last_reminded_on,opened_at,source_revision,handled_at,handled_by,handle_reason,reopened_from,reopen_reason FROM sim_expiry_rounds";
    private static boolean uuid(String value){return value!=null&&value.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");}
    private static boolean year(java.time.LocalDate value){return value!=null&&value.getYear()>=1&&value.getYear()<=9999;}
    private static boolean controls(String value){return value==null||value.chars().anyMatch(Character::isISOControl);}
    private static boolean validReason(String value){if(value==null||value.length()>Limits.MAX_CHANGE_REASON_LENGTH||value.chars().anyMatch(c->Character.isISOControl(c)&&c!='\r'&&c!='\n'&&c!='\t'))return false;try{java.nio.charset.StandardCharsets.UTF_8.newEncoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).encode(java.nio.CharBuffer.wrap(value));return true;}catch(java.nio.charset.CharacterCodingException e){return false;}}
    private Round round(ResultSet rs,String user)throws SQLException{
        String id=rs.getString("id");var reads=jdbc.query("SELECT read_at FROM sim_expiry_reads WHERE round_id=? AND user_id=?",(r,n)->timestamp(r.getObject(1,OffsetDateTime.class)),id,user);
        Round value=new Round(id,rs.getString("tenant_id"),rs.getString("target_kind"),rs.getString("target_id"),rs.getObject("expires_on",java.time.LocalDate.class),rs.getInt("generation"),rs.getString("state"),rs.getLong("revision"),rs.getLong("reminder_count"),rs.getObject("last_reminded_on",java.time.LocalDate.class),timestamp(rs.getObject("opened_at",OffsetDateTime.class)),timestamp(rs.getObject("handled_at",OffsetDateTime.class)),rs.getString("handled_by"),rs.getString("handle_reason"),rs.getString("reopened_from"),rs.getString("reopen_reason"),!reads.isEmpty(),reads.isEmpty()?null:reads.getFirst());
        long[] notices=jdbc.queryForObject("SELECT COUNT(*),COALESCE(MIN(sequence),0),COALESCE(MAX(sequence),0) FROM sim_expiry_notices WHERE round_id=?",(r,n)->new long[]{r.getLong(1),r.getLong(2),r.getLong(3)},id);boolean handled="HANDLED".equals(value.state());
        boolean target="CARD".equals(value.target_kind())?uuid(value.target_id()):"EMBEDDED".equals(value.target_kind())&&value.target_id()!=null&&!value.target_id().isEmpty()&&value.target_id().length()<=64&&!controls(value.target_id());
        boolean handle=handled?value.handled_at()!=null&&value.handled_by()!=null&&!value.handled_by().isEmpty()&&value.handle_reason()!=null&&!value.handle_reason().isBlank()&&validReason(value.handle_reason()):value.handled_at()==null&&value.handled_by()==null&&value.handle_reason()==null;
        boolean reopen=(value.reopened_from()==null&&value.reopen_reason()==null)||(uuid(value.reopened_from())&&value.reopen_reason()!=null&&!value.reopen_reason().isBlank()&&validReason(value.reopen_reason()));
        long sourceRevision=rs.getLong("source_revision");
        if(!uuid(id)||value.tenant_id()==null||value.tenant_id().isEmpty()||value.target_kind()==null||!target||!year(value.expires_on())||value.generation()<1||value.state()==null||!Set.of("OPEN","HANDLED","SUPERSEDED").contains(value.state())||value.revision()<1||value.revision()>9_007_199_254_740_991L||value.reminder_count()<1||!year(value.last_reminded_on())||!fixedTimestamp(value.opened_at())||(value.handled_at()!=null&&!fixedTimestamp(value.handled_at()))||!handle||!reopen||value.read_by_me()!=(value.read_at()!=null)||(value.read_at()!=null&&!fixedTimestamp(value.read_at()))||reads.size()>1||sourceRevision<0||notices[0]!=value.reminder_count()||notices[1]!=1||notices[2]!=value.reminder_count())throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","提醒轮次无法确认");
        return value;
    }
    public Round round(String tenant,String id,String user){String where=" WHERE tenant_id=? AND id=?";Object[] args={tenant,id};if(user!=null){var access=deviceScope.predicate(user,"d.tenant_id","d.id");where+=" AND (target_kind='CARD' OR (target_kind='EMBEDDED' AND EXISTS(SELECT 1 FROM devices d WHERE d.tenant_id=sim_expiry_rounds.tenant_id AND d.id=sim_expiry_rounds.target_id AND ("+access.sql()+"))))";args=concat(args,access.bindings().toArray());}var rows=jdbc.query(ROUND+where,(r,n)->round(r,user),args);if(rows.isEmpty())throw new ApiError(404,"NOT_FOUND","记录不存在");return rows.getFirst();}
    public Page<Round> rounds(String tenant,String user,String state,int page,Integer requested,boolean recipientOnly){Pagination p=pagination(page,requested);var access=deviceScope.predicate(user,"d.tenant_id","d.id");String where=" WHERE tenant_id=?"+(state==null?"":" AND state=?")+" AND (target_kind='CARD' OR (target_kind='EMBEDDED' AND EXISTS(SELECT 1 FROM devices d WHERE d.tenant_id=sim_expiry_rounds.tenant_id AND d.id=sim_expiry_rounds.target_id AND ("+access.sql()+"))))"+(recipientOnly?" AND EXISTS(SELECT 1 FROM sim_expiry_recipients x WHERE x.tenant_id=sim_expiry_rounds.tenant_id AND x.user_id=? AND x.user_id IN (SELECT u.id FROM app_users u JOIN user_tenant_grants g ON g.user_id=u.id WHERE g.tenant_id=? AND u.enabled=TRUE AND u.must_change_password=FALSE AND u.user_type='PLATFORM') AND EXISTS(SELECT 1 FROM effective_user_permissions p WHERE p.user_id=x.user_id AND p.permission='sim-expiry:read') AND EXISTS(SELECT 1 FROM sim_expiry_notices n WHERE n.round_id=sim_expiry_rounds.id AND n.created_at>=x.added_at))":"");var args=new ArrayList<Object>();args.add(tenant);if(state!=null)args.add(state);args.addAll(access.bindings());if(recipientOnly){args.add(user);args.add(tenant);}long total=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_rounds"+where,Long.class,args.toArray());var items=jdbc.query(ROUND+where+" ORDER BY expires_on,id LIMIT ? OFFSET ?",(r,n)->round(r,user),concat(args.toArray(),p.size(),p.offset()));return new Page<>(items,total,p.page(),p.size(),(int)(total/p.size()+(total%p.size()==0?0:1)));}
    public boolean received(String tenant,String user,String round){return jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_recipients x JOIN app_users u ON u.id=x.user_id AND u.user_type='PLATFORM' AND u.enabled=TRUE AND u.must_change_password=FALSE JOIN user_tenant_grants g ON g.user_id=u.id AND g.tenant_id=x.tenant_id JOIN effective_user_permissions p ON p.user_id=u.id AND p.permission='sim-expiry:read' WHERE x.tenant_id=? AND x.user_id=? AND EXISTS(SELECT 1 FROM sim_expiry_notices n WHERE n.round_id=? AND n.created_at>=x.added_at)",Long.class,tenant,user,round)>0;}
    private Object[] concat(Object[] a,Object...b){Object[] out=Arrays.copyOf(a,a.length+b.length);System.arraycopy(b,0,out,a.length,b.length);return out;}
}
